{"sample_id":"arvo_11484","fine_trace":[{"step":1,"file":"tests/fuzz/fuzz_binary_decode.cc","function":"tortureEncoding","line":34,"var":"dst","code":"UA_StatusCode ret = UA_decodeBinary(&binary, newOffset, dst, &UA_TYPES[typeIndex], NULL);","role":"source","note":"Fuzzer input decoded into DataValue containing a Variant with an array of DataValues and arrayDimensions"},{"step":2,"file":"src/ua_types_encoding_binary.c","function":"Variant_decodeBinary","line":1143,"var":"dst->data","code":"ret = Array_decodeBinary(&dst->data, &dst->arrayLength, dst->type, ctx);","role":"intermediate","note":"Variant data array (1 DataValue element) successfully decoded and allocated"},{"step":3,"file":"src/ua_types_encoding_binary.c","function":"Variant_decodeBinary","line":1155,"var":"dst->arrayDimensions","code":"ret |= Array_decodeBinary((void**)&dst->arrayDimensions, &dst->arrayDimensionsSize, &UA_TYPES[UA_TYPES_INT32], ctx);","role":"intermediate","note":"Variant arrayDimensions decoded successfully during initial decode phase"},{"step":4,"file":"tests/fuzz/fuzz_binary_decode.cc","function":"tortureEncoding","line":38,"var":"dstCopy","code":"UA_copy(dst, dstCopy, &UA_TYPES[typeIndex]);","role":"intermediate","note":"UA_copy called on decoded DataValue, triggers the vulnerable copy path"},{"step":5,"file":"src/ua_types.c","function":"Variant_copy","line":421,"var":"dst->data","code":"UA_StatusCode retval = UA_Array_copy(src->data, length, &dst->data, src->type);","role":"intermediate","note":"Variant_copy allocates and copies the DataValue array into dst->data successfully"},{"step":6,"file":"src/ua_types.c","function":"Variant_copy","line":428,"var":"dst->arrayDimensions","code":"retval = UA_Array_copy(src->arrayDimensions, src->arrayDimensionsSize, (void**)&dst->arrayDimensions, &UA_TYPES[UA_TYPES_INT32]);","role":"root_cause","note":"arrayDimensions copy fails due to memory limit; Variant_copy returns error without freeing dst->data, leaving dst->type and dst->data set with allocated array"},{"step":7,"file":"src/ua_types.c","function":"DataValue_copy","line":810,"var":"dst","code":"DataValue_clear(dst, NULL);","role":"intermediate","note":"DataValue_copy error path calls DataValue_clear which calls Variant_clear, freeing dst->data via UA_Array_delete but NOT zeroing dst->value.type or dst->value.data"},{"step":8,"file":"src/ua_types.c","function":"Variant_clear","line":410,"var":"p->data","code":"UA_Array_delete(p->data, p->arrayLength, p->type);","role":"intermediate","note":"First Variant_clear frees the data array; after UA_Array_delete, p->data and p->type remain as dangling values"},{"step":9,"file":"src/ua_types.c","function":"UA_copy","line":960,"var":"dst","code":"UA_clear(dst, type);","role":"intermediate","note":"UA_copy error handler calls UA_clear on dstCopy which still has dangling variant pointers"},{"step":10,"file":"src/ua_types.c","function":"DataValue_clear","line":799,"var":"p->value","code":"Variant_clear(&p->value, NULL);","role":"sink","note":"Second DataValue_clear via clear_noInit calls Variant_clear on the variant with dangling type/data pointers; UA_Array_delete reads from freed DataValue array memory causing heap-use-after-free READ 4 on storageType field"}],"vuln_logic":{"source":{"file":"tests/fuzz/fuzz_binary_decode.cc","function":"tortureEncoding","line":34,"operands":["dst","data"]},"root_cause":{"file":"src/ua_types.c","function":"Variant_copy","line":428,"operands":["dst->data","dst->arrayDimensions"],"relation":{"op":"eq","left":"dst->data","right":"NULL"}},"sink":{"file":"src/ua_types.c","function":"DataValue_clear","line":799,"operands":["p->value.data","p->value.type"],"relation":{"op":"ne","left":"p->value.data","right":"NULL"}},"propagation":[{"from":{"file":"tests/fuzz/fuzz_binary_decode.cc","function":"tortureEncoding","line":34,"operands":["dst"]},"to":{"file":"src/ua_types.c","function":"Variant_copy","line":421,"operands":["dst->data"]},"type":"data","via":["UA_copy","copy_noInit","DataValue_copy","Variant_copy"]},{"from":{"file":"src/ua_types.c","function":"Variant_copy","line":428,"operands":["retval"]},"to":{"file":"src/ua_types.c","function":"DataValue_copy","line":810,"operands":["dst"]},"type":"control","via":["retval"]},{"from":{"file":"src/ua_types.c","function":"Variant_clear","line":410,"operands":["p->data"]},"to":{"file":"src/ua_types.c","function":"DataValue_clear","line":799,"operands":["p->value.data"]},"type":"data","via":["p->value.data","p->value.type"]}]}}
